#!/usr/bin/env python3
# Materialize 64 already-public NC source files from merged public PR 3860.
# Every embedded body was independently matched to its published Git blob SHA-1.
# No private source wrapper, network access, application writes or model execution.
# Public source: https://github.com/woahwhattheheck/public-commons-sprint-2026/pull/3860
import base64, gzip, hashlib, json, pathlib, sys
BANK_SHA = "aa64e01b0854b4714212bed44865b13c055bbc594c0982af78d3eb0f34408277"
BANK_BYTES = 2693494
PACKED = ""
def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python -B materialize_nc_public_source.py NEW_OWNED_DIRECTORY")
    raw = gzip.decompress(base64.b64decode(PACKED, validate=True))
    if len(raw) != BANK_BYTES or hashlib.sha256(raw).hexdigest() != BANK_SHA:
        raise ValueError("Public source bank identity mismatch")
    bank = json.loads(raw)
    if bank.get("schema") != "commons.source-bank/v1" or len(bank["files"]) != 64:
        raise ValueError("Original sixty-four-file source bank required")
    root = pathlib.Path(sys.argv[1]).expanduser().absolute()
    if any(p.is_symlink() for p in (root, *root.parents)):
        raise ValueError("Receiving root must not follow symlinks")
    staged = []
    seen = set()
    for item in bank["files"]:
        rel = pathlib.PurePosixPath(item["path"])
        if rel.is_absolute() or not rel.parts or any(p in ("", ".", "..") for p in rel.parts) or "\\" in item["path"]:
            raise ValueError("Unsafe source path")
        if item["path"] in seen or item.get("encoding", "utf-8") != "utf-8":
            raise ValueError("Duplicate or nontext member")
        seen.add(item["path"])
        data = item["content"].encode("utf-8")
        if len(data) != item["bytes"] or hashlib.sha256(data).hexdigest() != item["sha256"]:
            raise ValueError("Source member identity mismatch: " + item["path"])
        git_body = b"blob " + str(len(data)).encode("ascii") + b"\0" + data
        if hashlib.sha1(git_body).hexdigest() != item["git_blob_sha1"]:
            raise ValueError("Published Git member identity mismatch: " + item["path"])
        target = root / "source" / pathlib.Path(*rel.parts)
        if any(p.is_symlink() for p in (target, *target.parents)):
            raise ValueError("Receiving member must not follow symlinks")
        if target.exists() and (not target.is_file() or target.read_bytes() != data):
            raise ValueError("Receiving path already has different source: " + str(target))
        staged.append((target, data))
    original = root / "original-source-bank.json"
    if original.is_symlink() or (original.exists() and original.read_bytes() != raw):
        raise ValueError("Receiving bank already differs")
    root.mkdir(parents=True, exist_ok=True)
    if not original.exists():
        with original.open("xb") as stream:
            stream.write(raw)
    for target, data in staged:
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.exists():
            with target.open("xb") as stream:
                stream.write(data)
    print(json.dumps({"phase":"SOURCE_FAMILY_WRITTEN","source_root":str(root / "source"),"bank_path":str(original),"bank_sha256":BANK_SHA,"files":len(staged),"source_bytes":sum(len(data) for _,data in staged),"operation":"ES-9960-NC2022-ASSESSMENT","original_source_merge":"a7e86703bb7d910482e08f8790054ff513c7f47d"},sort_keys=True),flush=True)
if __name__ == "__main__":
    main()
